"""
Rate Limiting Module

Implements a sliding window counter algorithm to prevent resource abuse.
Tracks actions per agent within a configurable time window.
"""

from typing import Dict, Deque, Optional
from collections import deque
from datetime import datetime, timedelta
import time
import threading


class RateLimitExceeded(Exception):
    """Custom exception for rate limit violations."""
    def __init__(self, agent_id: str, limit: int, window_seconds: int):
        self.agent_id = agent_id
        self.limit = limit
        self.window_seconds = window_seconds
        super().__init__(
            f"Rate limit exceeded for agent {agent_id}: "
            f"maximum {limit} requests per {window_seconds} seconds"
        )


class RateLimiter:
    """
    Sliding window counter rate limiter.
    Thread-safe implementation for high-concurrency environments.
    """

    def __init__(self, default_limit: int = 100, default_window: int = 60):
        """
        Initialize the rate limiter.

        Args:
            default_limit: Maximum number of actions allowed in the window
            default_window: Time window in seconds
        """
        self.default_limit = default_limit
        self.default_window = default_window
        self._windows: Dict[str, Deque[float]] = {}
        self._lock = threading.Lock()

    def _get_window(self, agent_id: str) -> Deque[float]:
        """Get or create the sliding window for an agent."""
        if agent_id not in self._windows:
            self._windows[agent_id] = deque()
        return self._windows[agent_id]

    def _cleanup_window(self, window: Deque[float], window_seconds: int):
        """Remove timestamps outside the current window."""
        cutoff = time.time() - window_seconds
        while window and window[0] < cutoff:
            window.popleft()

    def check_rate_limit(
        self,
        agent_id: str,
        limit: Optional[int] = None,
        window_seconds: Optional[int] = None
    ) -> bool:
        """
        Check if an agent has exceeded their rate limit.

        Args:
            agent_id: The agent to check
            limit: Maximum actions allowed (defaults to instance default)
            window_seconds: Time window in seconds (defaults to instance default)

        Returns:
            True if the action is allowed, False if rate limited

        Raises:
            RateLimitExceeded: If the rate limit is exceeded
        """
        limit = limit or self.default_limit
        window_seconds = window_seconds or self.default_window

        with self._lock:
            window = self._get_window(agent_id)
            self._cleanup_window(window, window_seconds)

            if len(window) >= limit:
                raise RateLimitExceeded(agent_id, limit, window_seconds)

            # Record the action
            window.append(time.time())
            return True

    def get_remaining(
        self,
        agent_id: str,
        limit: Optional[int] = None,
        window_seconds: Optional[int] = None
    ) -> int:
        """
        Get the number of remaining actions for an agent.

        Args:
            agent_id: The agent to check
            limit: Maximum actions allowed
            window_seconds: Time window in seconds

        Returns:
            Number of remaining actions
        """
        limit = limit or self.default_limit
        window_seconds = window_seconds or self.default_window

        with self._lock:
            window = self._get_window(agent_id)
            self._cleanup_window(window, window_seconds)
            return max(0, limit - len(window))

    def reset_agent(self, agent_id: str):
        """Reset the rate limit counter for a specific agent."""
        with self._lock:
            if agent_id in self._windows:
                del self._windows[agent_id]

    def get_active_agents(self) -> int:
        """Get the number of agents currently being tracked."""
        with self._lock:
            return len(self._windows)